import org.apache.http.util.EntityUtils;

import java.io.IOException;
import java.io.InputStream;
import java.net.URL;
import java.util.Scanner;

/**
 * Service class for fetching URL content.
 */
public class UrlService {

    /**
     * Fetches the content of a given URL using Apache HttpClient for HTTP/HTTPS,
     * and Java's URL class for file protocol.
     *
     * @param userUrl the URL string provided by the user
     * @return the response body as a string
     * @throws IllegalArgumentException if the URL is null or empty
     * @throws IOException if the request fails or the response cannot be read
     */
    public String fetchUrlContent(String userUrl) throws IOException {
        if (userUrl == null || userUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("URL must not be null or empty");
        }

        // Handle file:// protocol
        if (userUrl.startsWith("file://")) {
            URL url = new URL(userUrl);
            String host = url.getHost();
            // If the file URL has a non-empty host, treat it as an HTTP URL
            if (host != null && !host.isEmpty()) {
                String httpUrl = "http://" + host + url.getPath();
                return fetchHttpContent(httpUrl);
            }
            // Otherwise, read the local file
            try (InputStream is = url.openStream();
                 Scanner scanner = new Scanner(is, "UTF-8")) {
                scanner.useDelimiter("\\A");
                return scanner.hasNext() ? scanner.next() : "";
            }
        }

        // For HTTP/HTTPS, use Apache HttpClient
        return fetchHttpContent(userUrl);
    }

    /**
     * Fetches content from an HTTP/HTTPS URL using Apache HttpClient.
     */
    private String fetchHttpContent(String url) throws IOException {
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            HttpGet httpGet = new HttpGet(url);
            try (CloseableHttpResponse response = httpClient.execute(httpGet)) {
                int statusCode = response.getStatusLine().getStatusCode();
                if (statusCode < 200 || statusCode >= 300) {
                    throw new IOException("Unexpected response status: " + statusCode);
                }
                return EntityUtils.toString(response.getEntity());
            }
        }
    }
}

